import React, { useCallback, useRef, useState } from 'react';
import { LiveboardEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { Action } from '@thoughtspot/visual-embed-sdk';
import {
  TOP_HEADER_PX,
  LIVEBOARD_NO_HEADER_CUSTOMIZATIONS,
} from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

// ─── Constants ────────────────────────────────────────────────────────────────

const BG          = '#F0F2FF';
const LABEL       = 'rgba(0,0,0,0.45)';
const EMBED_MIN_H = `calc(100vh - ${TOP_HEADER_PX}px - 160px)`;
const BLUE        = '#2B3CC1';
const NAVY        = '#0F1875';

const ONCOMMERCE_OVERVIEW_LIVEBOARD_ID = '5e3313c4-d293-4218-a9c5-af117f7c3015';

const LIVEBOARD_TABS = [
  { id: 'tab1', label: 'Overview', tabId: '1c8444c3-2baf-4acc-8541-fcaca51a8e9f' },
  { id: 'tab2', label: 'Detail',   tabId: '00e30fcb-7f53-4619-84ab-b7a9e3a69272' },
];

const AI_HIGHLIGHTS_TAB_ID = 'ai-highlights';

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function DashboardHome() {
  const { tier, hiddenActions, disabledActions } = useTier();
  const isPro = tier === 'Pro';
  const [selectedTab, setSelectedTab] = useState('tab1');
  const liveboardRef = useRef<any>(null);

  const allTabs = isPro
    ? [...LIVEBOARD_TABS, { id: AI_HIGHLIGHTS_TAB_ID, label: '✦ AI Highlights', tabId: '' }]
    : LIVEBOARD_TABS;

  const active = allTabs.find((t) => t.id === selectedTab) ?? allTabs[0];
  const isAIHighlightsTab = active.id === AI_HIGHLIGHTS_TAB_ID;

  const onError = useCallback(
    (err: { data?: { errorMessage?: string }; message?: string }) => {
      console.error('[ThoughtSpot Liveboard]', formatThoughtSpotEmbedError(err), err);
    },
    []
  );

  return (
    <div style={{ backgroundColor: BG, minHeight: `calc(100vh - ${TOP_HEADER_PX}px)` }}>

      {/* ── Page header ── */}
      <div style={{ padding: '1.75rem 2.5rem 1rem' }}>
        <div style={{ fontSize: 10, fontWeight: 600, letterSpacing: '0.12em', textTransform: 'uppercase', color: LABEL, marginBottom: 6 }}>
          OnCommerce
        </div>
        <h1 style={{ fontSize: 26, fontWeight: 800, color: NAVY, margin: '0 0 1rem', letterSpacing: '-0.03em' }}>
          Commerce Overview
        </h1>

        {/* Tab pill switcher */}
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
          {allTabs.map((tab) => {
            const isActive = tab.id === selectedTab;
            const isAI = tab.id === AI_HIGHLIGHTS_TAB_ID;
            return (
              <button
                key={tab.id}
                type="button"
                onClick={() => setSelectedTab(tab.id)}
                style={{
                  padding: '7px 20px',
                  borderRadius: 6,
                  border: isAI
                    ? `1px solid ${isActive ? BLUE : 'rgba(43,60,193,0.35)'}` 
                    : `1px solid ${isActive ? BLUE : 'rgba(0,0,0,0.15)'}`,
                  background: isActive ? BLUE : isAI ? 'rgba(43,60,193,0.07)' : '#FFFFFF',
                  color: isActive ? '#FFFFFF' : isAI ? BLUE : 'rgba(17,17,17,0.70)',
                  fontSize: 13.5,
                  fontWeight: isActive || isAI ? 600 : 400,
                  cursor: 'pointer',
                  transition: 'all 0.15s ease',
                  whiteSpace: 'nowrap',
                  letterSpacing: '-0.01em',
                  display: 'flex',
                  alignItems: 'center',
                  gap: 6,
                }}
              >
                {tab.label}
                {isAI && !isActive && (
                  <span style={{
                    fontSize: 9,
                    fontWeight: 700,
                    letterSpacing: '0.06em',
                    textTransform: 'uppercase',
                    background: BLUE,
                    color: '#fff',
                    borderRadius: 4,
                    padding: '1px 5px',
                    lineHeight: '14px',
                  }}>Pro</span>
                )}
              </button>
            );
          })}
        </div>
      </div>

      {/* ── Liveboard / AI Highlights embed ── */}
      <div style={{ padding: '0 2.5rem 2rem' }}>
        {isAIHighlightsTab ? (
          /* ── AI Highlights panel (Pro only) ── */
          <div>
            {/* Pro badge banner */}
            <div style={{
              display: 'flex',
              alignItems: 'center',
              gap: 12,
              background: 'linear-gradient(135deg, rgba(43,60,193,0.08) 0%, rgba(43,60,193,0.04) 100%)',
              border: '1px solid rgba(43,60,193,0.18)',
              borderRadius: 10,
              padding: '14px 20px',
              marginBottom: 16,
            }}>
              <div style={{
                width: 36, height: 36,
                borderRadius: 8,
                background: BLUE,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                flexShrink: 0,
                fontSize: 18,
              }}>✦</div>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 14, fontWeight: 700, color: NAVY, letterSpacing: '-0.01em' }}>
                  AI Highlights
                  <span style={{
                    marginLeft: 8,
                    fontSize: 9.5,
                    fontWeight: 700,
                    letterSpacing: '0.07em',
                    textTransform: 'uppercase',
                    background: BLUE,
                    color: '#fff',
                    borderRadius: 4,
                    padding: '2px 6px',
                    verticalAlign: 'middle',
                  }}>Pro</span>
                </div>
                <div style={{ fontSize: 12.5, color: 'rgba(31,33,36,0.55)', marginTop: 2 }}>
                  AI-generated insights surface the most significant trends and anomalies across your commerce data.
                </div>
              </div>
            </div>

            {/* Liveboard embed with all AI Highlights actions exposed */}
            <div style={{ backgroundColor: '#FFFFFF', borderRadius: 10, overflow: 'visible', minHeight: EMBED_MIN_H, border: '1px solid rgba(43,60,193,0.10)' }}>
              <LiveboardEmbed
                key="ai-highlights-embed"
                ref={liveboardRef}
                liveboardId={ONCOMMERCE_OVERVIEW_LIVEBOARD_ID}
                activeTabId={LIVEBOARD_TABS[0].tabId}
                fullHeight
                hideTabPanel
                isLiveboardStylingAndGroupingEnabled
                hiddenActions={hiddenActions.filter((a) => a !== Action.AIHighlights)}
                disabledActions={disabledActions}
                customizations={LIVEBOARD_NO_HEADER_CUSTOMIZATIONS}
                onError={onError}
                style={{ width: '100%', minHeight: EMBED_MIN_H, display: 'block', border: 'none' }}
              />
            </div>
          </div>
        ) : (
          <div style={{ backgroundColor: '#FFFFFF', borderRadius: 10, overflow: 'visible', minHeight: EMBED_MIN_H, border: '1px solid rgba(43,60,193,0.10)' }}>
            <LiveboardEmbed
              key={active.tabId}
              ref={liveboardRef}
              liveboardId={ONCOMMERCE_OVERVIEW_LIVEBOARD_ID}
              activeTabId={active.tabId}
              fullHeight
              hideTabPanel
              isLiveboardStylingAndGroupingEnabled
              hiddenActions={hiddenActions}
              disabledActions={disabledActions}
              customizations={LIVEBOARD_NO_HEADER_CUSTOMIZATIONS}
              onError={onError}
              style={{ width: '100%', minHeight: EMBED_MIN_H, display: 'block', border: 'none' }}
            />
          </div>
        )}
      </div>
    </div>
  );
}
